const body = $input.first().json.body || {};

// Support RFC-014 structure: data in context.* with fallback to root level
const ctx = body.context || {};

// Valider l'entrée - check both structures
const hasFile = !!(ctx.file_url || ctx.file_base64 || body.file_url || body.file_base64);
const hasJobId = !!(body.job_id || ctx.job_id);

if (!hasFile || !hasJobId) {
  return {
    json: {
      valid: false,
      response: {
        success: false,
        error: {
          code: 'INVALID_FORMAT',
          message: 'Missing required fields: file_url/file_base64 and job_id'
        }
      },
      status_code: 400
    }
  };
}

// Extraire le contexte - prefer context.* over root level (RFC-014)
const context = {
  job_id: body.job_id || ctx.job_id,
  conversation_id: body.conversation_id || ctx.conversation_id,
  user_id: body.user_id || ctx.user_id,
  guild_id: body.guild_id || ctx.guild_id,
  channel_id: body.channel_id || ctx.channel_id,
  file_url: ctx.file_url || body.file_url,
  file_base64: ctx.file_base64 || body.file_base64,
  file_type: ctx.file_type || body.file_type || 'pdf',
  action: body.action || ctx.action || 'translate',
  params: body.params || ctx.params || {},
  plugin_context: body.plugin_context || ctx.plugin_context || {},
  callback_url: body.callback_url || ctx.callback_url,
  start_time: Date.now()
};

// Vérifier si custom action et récupérer l'URL
const customActions = context.plugin_context?.custom_actions || {};
const isCustomAction = Object.keys(customActions).includes(context.action);
const customWebhookUrl = isCustomAction ? customActions[context.action]?.webhook_url : null;

// Valider l'URL du webhook custom
if (isCustomAction && !customWebhookUrl) {
  return {
    json: {
      valid: false,
      response: {
        success: false,
        error: {
          code: 'INVALID_CONFIG',
          message: `Custom action '${context.action}' has no webhook_url configured`
        }
      },
      status_code: 400
    }
  };
}

return {
  json: {
    valid: true,
    response: {
      success: true,
      message: 'Processing started',
      job_id: context.job_id
    },
    status_code: 200,
    context: context,
    is_custom_action: isCustomAction,
    custom_webhook_url: customWebhookUrl
  }
};

const input = $input.first().json;

// Si invalide, on s'arrête
if (!input.valid) {
  return [];
}

// Continuer avec le contexte
return {
  json: input
};

const result = $input.first().json;
const prevNode = $('Check Valid').first().json;
const context = prevNode.context;
const startTime = context.start_time;
const processingTime = Date.now() - startTime;

// Déterminer si succès ou erreur
const isSuccess = result.success !== false && !result.error;
const hasData = result.data || result.text || result.result;

let callback;

if (isSuccess && hasData) {
  // Succès
  const text = result.data?.text || result.data?.translated_text || result.text || JSON.stringify(result.data || result);
  callback = {
    job_id: context.job_id,
    conversation_id: context.conversation_id,
    user_id: context.user_id,
    guild_id: context.guild_id,
    channel_id: context.channel_id,
    success: true,
    result: {
      text: text,
      output_type: 'text',
      word_count: text.split(/\s+/).length
    },
    metrics: {
      tokens_used: result.meta?.usage?.total_tokens || result.usage?.total_tokens || Math.ceil(text.length / 4),
      processing_time_ms: processingTime,
      ocr_confidence: result.meta?.ocr_confidence || result.data?.ocr_confidence || 0.9,
      pages_processed: result.meta?.usage?.pages_processed || result.data?.page_count || 1
    },
    error: null
  };
} else {
  // Erreur
  const errorCode = result.error?.code || result.error?.status || 'INTERNAL_ERROR';
  const errorMessage = result.error?.message || 'Processing failed';

  callback = {
    job_id: context.job_id,
    conversation_id: context.conversation_id,
    user_id: context.user_id,
    guild_id: context.guild_id,
    channel_id: context.channel_id,
    success: false,
    result: null,
    metrics: {
      tokens_used: 0,
      processing_time_ms: processingTime,
      ocr_confidence: 0,
      pages_processed: 0
    },
    error: {
      code: errorCode,
      message: errorMessage,
      retriable: ['LLM_RATE_LIMITED', 'TIMEOUT', 'INTERNAL_ERROR'].includes(errorCode),
      refund: {
        recommended: true,
        percentage: errorCode === 'PARTIAL_SUCCESS' ? 50 : 100,
        reason: `Processing failed: ${errorMessage}`
      }
    }
  };
}

return {
  json: {
    callback: callback,
    callback_url: context.callback_url
  }
};

const input = $input.first().json;

// Si pas de callback URL, on log seulement
if (!input.callback_url) {
  return {
    json: {
      status: 'no_callback',
      callback: input.callback
    }
  };
}

// Envoyer le callback
try {
  const response = await fetch(input.callback_url, {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify(input.callback)
  });

  return {
    json: {
      status: 'callback_sent',
      callback_status: response.status,
      callback: input.callback
    }
  };
} catch (error) {
  return {
    json: {
      status: 'callback_failed',
      error: error.message,
      callback: input.callback
    }
  };
}
